public class ExpressGatewayServiceFactory(string resourceName = null, Action<Humidifier.ECS.ExpressGatewayService> factoryAction = null) : ResourceFactory<Humidifier.ECS.ExpressGatewayService>(resourceName)
{

    internal InnerExpressGatewayServiceExpressGatewayContainerFactory PrimaryContainerFactory { get; set; }

    internal InnerExpressGatewayServiceExpressGatewayScalingTargetFactory ScalingTargetFactory { get; set; }

    internal InnerExpressGatewayServiceExpressGatewayServiceNetworkConfigurationFactory NetworkConfigurationFactory { get; set; }

    protected override Humidifier.ECS.ExpressGatewayService Create()
    {
        var expressGatewayServiceResult = CreateExpressGatewayService();
        factoryAction?.Invoke(expressGatewayServiceResult);

        return expressGatewayServiceResult;
    }

    private Humidifier.ECS.ExpressGatewayService CreateExpressGatewayService()
    {
        var expressGatewayServiceResult = new Humidifier.ECS.ExpressGatewayService
        {
            GivenName = InputResourceName,
        };

        return expressGatewayServiceResult;
    }
    public override void CreateChildren(Humidifier.ECS.ExpressGatewayService result)
    {
        base.CreateChildren(result);

        result.PrimaryContainer ??= PrimaryContainerFactory?.Build();
        result.ScalingTarget ??= ScalingTargetFactory?.Build();
        result.NetworkConfiguration ??= NetworkConfigurationFactory?.Build();
    }

} // End Of Class

